5.6 Propiedades con @property (Forma Pythonica)
Python tiene una forma más elegante: el decorador @property

class Persona:
    def __init__(self, nombre, edad):
        self.__nombre = nombre
        self.__edad = edad

    # Propiedad para nombre (getter)
    @property
    def nombre(self):
        return self.__nombre

    # Setter para nombre
    @nombre.setter
    def nombre(self, nombre):
        if nombre and len(nombre.strip()) &gt; 0:
            self.__nombre = nombre
        else:
            raise ValueError("Nombre inválido")

    # Propiedad para edad (getter)
    @property
    def edad(self):
        return self.__edad

    # Setter para edad
    @edad.setter
    def edad(self, edad):
        if 0 &lt;= edad &lt;= 150:
            self.__edad = edad
        else:
            raise ValueError("Edad debe estar entre 0 y 150")

persona = Persona("Ana", 25)

# Ahora se usa como atributos normales
print(f"Nombre: {persona.nombre}")  # Sin paréntesis
print(f"Edad: {persona.edad}")

# Modificar (con validación)
persona.edad = 30
print(f"Nueva edad: {persona.edad}")

# Intentar valor inválido
try:
    persona.edad = 200
except ValueError as e:
    print(f"Error: {e}")

Nombre: Ana
Edad: 25
Nueva edad: 30
Error: Edad debe estar entre 0 y 150



5.6.1 Ventajas de @property

Sintaxis limpia: Se usa como atributo normal
Validación automática: El setter valida los datos
Retrocompatibilidad: Puedes convertir atributos públicos en propiedades sin romper código existente
Computed properties: Puedes calcular valores dinámicamente

5.7 Propiedades de Solo Lectura

class Rectangulo:
    def __init__(self, ancho, alto):
        self.__ancho = ancho
        self.__alto = alto

    @property
    def ancho(self):
        return self.__ancho

    @ancho.setter
    def ancho(self, ancho):
        if ancho &gt; 0:
            self.__ancho = ancho
        else:
            raise ValueError("Ancho debe ser positivo")

    @property
    def alto(self):
        return self.__alto

    @alto.setter
    def alto(self, alto):
        if alto &gt; 0:
            self.__alto = alto
        else:
            raise ValueError("Alto debe ser positivo")

    # Propiedad calculada (solo lectura)
    @property
    def area(self):
        return self.__ancho * self.__alto

    # Otra propiedad calculada
    @property
    def perimetro(self):
        return 2 * (self.__ancho + self.__alto)

rect = Rectangulo(5, 10)

print(f"Ancho: {rect.ancho}")
print(f"Alto: {rect.alto}")
print(f"Área: {rect.area}")  # Calculado automáticamente
print(f"Perímetro: {rect.perimetro}")

# Modificar dimensiones
rect.ancho = 7
print(f"\nNueva área: {rect.area}")  # Se recalcula automáticamente

# Intentar modificar área (error, no tiene setter)
try:
    rect.area = 100
except AttributeError as e:
    print(f"\nError: {e}")

