5.10.1 Ejercicio 1: Clase CuentaBancaria Completa
Crea una clase CuentaBancaria con:

Atributos privados: titular, saldo, numero_cuenta
Propiedades con validación para titular (no vacío) y saldo (no negativo)
Propiedad de solo lectura para numero_cuenta
Métodos: depositar, retirar
Propiedad calculada: saldo_formateado (retorna “$X,XXX.XX”)













TipSolución del ejercicio 1






class CuentaBancaria:
    _siguiente_numero = 1

    def __init__(self, titular, saldo=0):
        self.titular = titular          # Pasa por el setter (validación)
        self.saldo = saldo
        self.__numero_cuenta = f"CTA-{CuentaBancaria._siguiente_numero:04d}"
        CuentaBancaria._siguiente_numero += 1

    @property
    def titular(self):
        return self.__titular

    @titular.setter
    def titular(self, valor):
        if not valor or not valor.strip():
            raise ValueError("El titular no puede estar vacío")
        self.__titular = valor.strip()

    @property
    def saldo(self):
        return self.__saldo

    @saldo.setter
    def saldo(self, valor):
        if valor &lt; 0:
            raise ValueError("El saldo no puede ser negativo")
        self.__saldo = valor

    @property
    def numero_cuenta(self):  # Solo lectura: no tiene setter
        return self.__numero_cuenta

    @property
    def saldo_formateado(self):
        return f"${self.__saldo:,.2f}"

    def depositar(self, cantidad):
        if cantidad &lt;= 0:
            raise ValueError("La cantidad debe ser positiva")
        self.saldo += cantidad

    def retirar(self, cantidad):
        self.saldo -= cantidad  # El setter impide quedar en negativo

cuenta = CuentaBancaria("Ana López", 1500)
cuenta.depositar(2345.5)
print(cuenta.numero_cuenta, cuenta.titular, cuenta.saldo_formateado)

for accion in (lambda: cuenta.retirar(10_000),
               lambda: setattr(cuenta, "numero_cuenta", "X")):
    try:
        accion()
    except (ValueError, AttributeError) as e:
        print(f"{type(e).__name__}: {e}")

