5.10.2 Ejercicio 2: Clase Producto con Descuento
Crea una clase Producto con:

Atributos privados: nombre, precio, descuento_porcentaje (0-100)
Propiedades con validación para todos los atributos
Propiedad calculada: precio_final (precio - descuento)
Propiedad calculada: ahorro (cuánto se ahorra con el descuento)
Método: info() que muestra toda la información













TipSolución del ejercicio 2






class Producto:
    def __init__(self, nombre, precio, descuento_porcentaje=0):
        self.nombre = nombre
        self.precio = precio
        self.descuento_porcentaje = descuento_porcentaje

    @property
    def nombre(self):
        return self.__nombre

    @nombre.setter
    def nombre(self, valor):
        if not valor.strip():
            raise ValueError("Nombre vacío")
        self.__nombre = valor

    @property
    def precio(self):
        return self.__precio

    @precio.setter
    def precio(self, valor):
        if valor &lt;= 0:
            raise ValueError("El precio debe ser positivo")
        self.__precio = valor

    @property
    def descuento_porcentaje(self):
        return self.__descuento

    @descuento_porcentaje.setter
    def descuento_porcentaje(self, valor):
        if not 0 &lt;= valor &lt;= 100:
            raise ValueError("El descuento debe estar entre 0 y 100")
        self.__descuento = valor

    @property
    def ahorro(self):
        return self.__precio * self.__descuento / 100

    @property
    def precio_final(self):
        return self.__precio - self.ahorro

    def info(self):
        print(f"{self.nombre}: ${self.precio:.2f} - {self.descuento_porcentaje}% "
              f"= ${self.precio_final:.2f} (ahorras ${self.ahorro:.2f})")

p = Producto("Monitor", 4200, 15)
p.info()
p.descuento_porcentaje = 25   # El precio final se recalcula solo
p.info()
try:
    p.descuento_porcentaje = 120
except ValueError as e:
    print("Error:", e)

Monitor: $4200.00 - 15% = $3570.00 (ahorras $630.00)
Monitor: $4200.00 - 25% = $3150.00 (ahorras $1050.00)
