5.10.3 Ejercicio 3: Clase Estudiante con Promedio
Crea una clase Estudiante con:

Atributos privados: nombre, matricula, calificaciones (lista)
Propiedades con getters y setters para nombre y matrícula
Método: agregar_calificacion(calificacion) con validación (0-10)
Propiedad calculada de solo lectura: promedio
Propiedad calculada de solo lectura: estado (“Aprobado” si promedio &gt;= 6, “Reprobado” si &lt; 6)
Propiedad de solo lectura: total_materias (número de calificaciones)













TipSolución del ejercicio 3






class Estudiante:
    def __init__(self, nombre, matricula):
        self.nombre = nombre
        self.matricula = matricula
        self.__calificaciones = []

    @property
    def nombre(self):
        return self.__nombre

    @nombre.setter
    def nombre(self, valor):
        if not valor.strip():
            raise ValueError("Nombre vacío")
        self.__nombre = valor

    @property
    def matricula(self):
        return self.__matricula

    @matricula.setter
    def matricula(self, valor):
        if not valor.strip():
            raise ValueError("Matrícula vacía")
        self.__matricula = valor

    def agregar_calificacion(self, calificacion):
        if not 0 &lt;= calificacion &lt;= 10:
            raise ValueError("La calificación debe estar entre 0 y 10")
        self.__calificaciones.append(calificacion)

    @property
    def promedio(self):
        if not self.__calificaciones:
            return 0
        return sum(self.__calificaciones) / len(self.__calificaciones)

    @property
    def estado(self):
        return "Aprobado" if self.promedio &gt;= 6 else "Reprobado"

    @property
    def total_materias(self):
        return len(self.__calificaciones)

est = Estudiante("Diego", "219876")
for c in [8, 5.5, 9, 7]:
    est.agregar_calificacion(c)
print(f"{est.nombre}: {est.total_materias} materias, "
      f"promedio {est.promedio:.2f} -&gt; {est.estado}")

Diego: 4 materias, promedio 7.38 -&gt; Aprobado







5.10.4 Ejercicio 4: Sistema de Gestión de Contraseñas (Desafío)
Crea una clase Usuario con:

Atributos privados:

username (solo lectura después de crear)
__password_hash (nunca exponer directamente)
email
fecha_creacion (solo lectura)
intentos_fallidos (privado)

Propiedades:

username (solo getter)
email (getter y setter con validación de formato)
fecha_creacion (solo getter)
cuenta_bloqueada (solo getter, True si intentos_fallidos &gt;= 3)

Métodos:

cambiar_password(password_actual, password_nueva): Valida la actual y cambia
verificar_password(password): Retorna True/False, incrementa intentos_fallidos
desbloquear_cuenta(): Resetea intentos_fallidos (solo si conoces la password)
validar_fortaleza_password(password): Retorna True si cumple:

Al menos 8 caracteres
Al menos una mayúscula
Al menos una minúscula
Al menos un número



Simula hash de password con: hash(password) (no usar en producción real)












TipSolución del ejercicio 4






import re
from datetime import datetime

class Usuario:
    MAX_INTENTOS = 3

    def __init__(self, username, password, email):
        if not Usuario.validar_fortaleza_password(password):
            raise ValueError("Contraseña débil")
        self.__username = username
        self.__password_hash = hash(password)   # Solo para el ejemplo
        self.email = email
        self.__fecha_creacion = datetime.now()
        self.__intentos_fallidos = 0

    @property
    def username(self):
        return self.__username

    @property
    def fecha_creacion(self):
        return self.__fecha_creacion

    @property
    def email(self):
        return self.__email

    @email.setter
    def email(self, valor):
        if not re.match(r"^[\w.+-]+@[\w-]+\.[\w.]+$", valor):
            raise ValueError("Email inválido")
        self.__email = valor

    @property
    def cuenta_bloqueada(self):
        return self.__intentos_fallidos &gt;= Usuario.MAX_INTENTOS

    @staticmethod
    def validar_fortaleza_password(password):
        return (len(password) &gt;= 8
                and any(c.isupper() for c in password)
                and any(c.islower() for c in password)
                and any(c.isdigit() for c in password))

    def verificar_password(self, password):
        if self.cuenta_bloqueada:
            return False
        if hash(password) == self.__password_hash:
            self.__intentos_fallidos = 0
            return True
        self.__intentos_fallidos += 1
        return False

    def cambiar_password(self, password_actual, password_nueva):
        if not self.verificar_password(password_actual):
            return "Contraseña actual incorrecta"
        if not Usuario.validar_fortaleza_password(password_nueva):
            return "La nueva contraseña es débil"
        self.__password_hash = hash(password_nueva)
        return "Contraseña actualizada"

    def desbloquear_cuenta(self, password):
        if hash(password) == self.__password_hash:
            self.__intentos_fallidos = 0
            return True
        return False

u = Usuario("ana_dev", "Segura123", "ana@correo.com")
print("Fortaleza de 'abc':", Usuario.validar_fortaleza_password("abc"))
print(u.cambiar_password("Segura123", "MasSegura456"))
for intento in ["mala1", "mala2", "mala3"]:
    u.verificar_password(intento)
print("¿Bloqueada?", u.cuenta_bloqueada)
print("¿Entra con la correcta?", u.verificar_password("MasSegura456"))
print("Desbloqueo:", u.desbloquear_cuenta("MasSegura456"), "| ¿Bloqueada?", u.cuenta_bloqueada)
print("Creada:", u.fecha_creacion.strftime("%Y-%m-%d"))

