7.10.1 Ejercicio 1: Clase Fraccion
Crea una clase Fraccion que represente fracciones matemáticas:

Constructor: Fraccion(numerador, denominador)
__str__: Muestra como “3/4”
__add__: Suma de fracciones
__sub__: Resta de fracciones
__mul__: Multiplicación de fracciones
__truediv__: División de fracciones
__eq__: Compara si son iguales
__float__: Convierte a decimal

Bonus: Simplifica automáticamente las fracciones.












TipSolución del ejercicio 1






from math import gcd

class Fraccion:
    def __init__(self, numerador, denominador=1):
        if denominador == 0:
            raise ZeroDivisionError("El denominador no puede ser 0")
        if denominador &lt; 0:                       # Signo siempre en el numerador
            numerador, denominador = -numerador, -denominador
        d = gcd(numerador, denominador)           # Bonus: simplificar
        self.num = numerador // d
        self.den = denominador // d

    def __str__(self):
        return f"{self.num}/{self.den}"

    def __repr__(self):
        return f"Fraccion({self.num}, {self.den})"

    def __add__(self, otra):
        return Fraccion(self.num * otra.den + otra.num * self.den, self.den * otra.den)

    def __sub__(self, otra):
        return Fraccion(self.num * otra.den - otra.num * self.den, self.den * otra.den)

    def __mul__(self, otra):
        return Fraccion(self.num * otra.num, self.den * otra.den)

    def __truediv__(self, otra):
        return Fraccion(self.num * otra.den, self.den * otra.num)

    def __eq__(self, otra):
        return self.num == otra.num and self.den == otra.den

    def __float__(self):
        return self.num / self.den

a, b = Fraccion(1, 2), Fraccion(3, 4)
print(f"{a} + {b} = {a + b}")
print(f"{a} - {b} = {a - b}")
print(f"{a} * {b} = {a * b}")
print(f"{a} / {b} = {a / b}")
print(f"2/4 == 1/2: {Fraccion(2, 4) == a}")
print(f"float({b}) = {float(b)}")

1/2 + 3/4 = 5/4
1/2 - 3/4 = -1/4
1/2 * 3/4 = 3/8
1/2 / 3/4 = 2/3
2/4 == 1/2: True
float(3/4) = 0.75







7.10.2 Ejercicio 2: Clase Dinero
Crea una clase Dinero para manejar cantidades monetarias:

Constructor: Dinero(cantidad, moneda="MXN")
__str__: Muestra como “$100.50 MXN”
__add__: Suma (solo si tienen la misma moneda)
__sub__: Resta (solo si tienen la misma moneda)
__mul__: Multiplica por un número
__eq__, __lt__, __gt__: Comparaciones
__bool__: False si cantidad es 0

Debe lanzar error si intentas sumar monedas diferentes.












TipSolución del ejercicio 2






class Dinero:
    def __init__(self, cantidad, moneda="MXN"):
        self.cantidad = cantidad
        self.moneda = moneda

    def _verificar_moneda(self, otro):
        if self.moneda != otro.moneda:
            raise ValueError(f"No se puede operar {self.moneda} con {otro.moneda}")

    def __str__(self):
        return f"${self.cantidad:,.2f} {self.moneda}"

    def __add__(self, otro):
        self._verificar_moneda(otro)
        return Dinero(self.cantidad + otro.cantidad, self.moneda)

    def __sub__(self, otro):
        self._verificar_moneda(otro)
        return Dinero(self.cantidad - otro.cantidad, self.moneda)

    def __mul__(self, factor):
        return Dinero(self.cantidad * factor, self.moneda)

    def __eq__(self, otro):
        return self.moneda == otro.moneda and self.cantidad == otro.cantidad

