class Matriz:
    def __init__(self, filas_o_datos, columnas=None):
        if columnas is not None:                     # Matriz(filas, columnas) → ceros
            self.datos = [[0] * columnas for _ in range(filas_o_datos)]
        else:                                        # Matriz(lista_de_listas)
            datos = filas_o_datos
            if not datos or any(len(f) != len(datos[0]) for f in datos):
                raise ValueError("Todas las filas deben tener la misma longitud")
            self.datos = [list(f) for f in datos]    # Copia defensiva

    def dimensiones(self):
        return len(self.datos), len(self.datos[0])

    def es_cuadrada(self):
        f, c = self.dimensiones()
        return f == c

    def transpuesta(self):
        return Matriz([list(col) for col in zip(*self.datos)])

    def _misma_dimension(self, otra):
        if self.dimensiones() != otra.dimensiones():
            raise ValueError(f"Dimensiones incompatibles: {self.dimensiones()} y {otra.dimensiones()}")

    def __len__(self):
        return len(self.datos)

    def __getitem__(self, i):
        return self.datos[i]          # m[i] devuelve la fila; m[i][j] el elemento

    def __setitem__(self, i, fila):
        self.datos[i] = fila

    def __add__(self, otra):
        self._misma_dimension(otra)
        return Matriz([[a + b for a, b in zip(f1, f2)] for f1, f2 in zip(self.datos, otra.datos)])

    def __sub__(self, otra):
        self._misma_dimension(otra)
        return Matriz([[a - b for a, b in zip(f1, f2)] for f1, f2 in zip(self.datos, otra.datos)])

    def __mul__(self, otro):
        if isinstance(otro, (int, float)):           # Por escalar
            return Matriz([[a * otro for a in fila] for fila in self.datos])
        if self.dimensiones()[1] != otro.dimensiones()[0]:
            raise ValueError("Columnas de A deben ser iguales a filas de B")
        cols = otro.transpuesta().datos
        return Matriz([[sum(a * b for a, b in zip(fila, col)) for col in cols] for fila in self.datos])

    def __rmul__(self, escalar):
        return self * escalar

    def __eq__(self, otra):
        return isinstance(otra, Matriz) and self.datos == otra.datos

    def __repr__(self):
        return f"Matriz({self.datos})"

    def __str__(self):
        ancho = max(len(str(x)) for fila in self.datos for x in fila)
        return "\n".join("| " + " ".join(f"{x:&gt;{ancho}}" for x in fila) + " |" for fila in self.datos)

